old="function makeProblem(){let pool=[[23,14],[32,18],[41,26],[43,25],[56,32],[67,24],[72,35],[84,16],[39,47],[58,43]];let p;if(S.node<=pool.length){p=pool[S.node-1]}else{let tries=0,key='';do{p=[20+Math.floor(Math.random()*7)*10+Math.ceil(Math.random()*9),10+Math.floor(Math.random()*4)*10+Math.ceil(Math.random()*9)];key=[...p].sort((a,b)=>a-b).join('x');tries++}while(key===S.prevProblemKey&&tries<40)}S.a=p[0];S.b=p[1];S.prevProblemKey=[S.a,S.b].sort((a,b)=>a-b).join('x');let A=splitNum(S.a),B=splitNum(S.b);S.parts=[[A[0],B[0]],[A[1],B[0]],[A[0],B[1]],[A[1],B[1]]];S.solved=[false,false,false,false];S.split=false;S.total=null;S.enemyMax=100+S.node*12;S.enemy=S.enemyMax;S.enemyKind=S.node%4;renderUI();setHint('Split both numbers. Then break the product into four smaller attacks.')}"
new="function makeProblem(){let pool=[[23,14],[32,18],[41,26],[43,25],[56,32],[67,24],[72,35],[84,16],[39,47],[58,43]];let p;if(S.node<=pool.length){p=pool[S.node-1]}else{let tries=0,key='';do{p=[20+Math.floor(Math.random()*7)*10+Math.ceil(Math.random()*9),10+Math.floor(Math.random()*4)*10+Math.ceil(Math.random()*9)];key=[...p].sort((a,b)=>a-b).join('x');tries++}while(key===S.prevProblemKey&&tries<40)}S.a=p[0];S.b=p[1];S.prevProblemKey=[S.a,S.b].sort((a,b)=>a-b).join('x');let A=splitNum(S.a),B=splitNum(S.b);S.parts=[[A[0],B[0]],[A[1],B[0]],[A[0],B[1]],[A[1],B[1]]];S.solved=[false,false,false,false];S.split=true;S.total=null;S.enemyMax=100+S.node*12;S.enemy=S.enemyMax;S.enemyKind=S.node%4;S.lastPart=-1;S.enemyCracks=0;S.enemyHit=0;S.comboBurst=0;renderUI();setHint('Each rectangle is a partial product. Charge all four, then combine them.')}"
