anchor="function termTap(i){if(!S.run||S.solved[i])return;"
helpers="function gridGeom(){let A=splitNum(S.a),B=splitNum(S.b),gw=Math.min(W*.7,250),gh=Math.min(H*.27,135),gx=(W-gw)/2,gy=H*.12;let vx=gx+gw*(A[0]/S.a),hy=gy+gh*(B[0]/S.b);return {A,B,gw,gh,gx,gy,vx,hy,rects:[{x:gx,y:gy,w:vx-gx,h:hy-gy},{x:vx,y:gy,w:gx+gw-vx,h:hy-gy},{x:gx,y:hy,w:vx-gx,h:gy+gh-hy},{x:vx,y:hy,w:gx+gw-vx,h:gy+gh-hy}]};}\nfunction spawnBeam(i,combine){let g=gridGeom(),r=g.rects[i],sx=r.x+r.w/2,sy=r.y+r.h/2;S.beams.push({x1:sx,y1:sy,x2:W*.5,y2:H*.47,t:combine?.65:.38,combine:!!combine});S.enemyHit=combine?.5:.28;S.enemyHitDir=(sx<W*.5?-1:1);S.enemyCracks=Math.min(8,S.enemyCracks+(combine?2:1));if(S.streak>=4)S.comboBurst=Math.min(1.2,.25+S.streak*.035);}\n"
