old="function answerTerm(i,v,ans){if(v===ans){S.solved[i]=true;S.streak++;let dmg=14+Math.min(18,S.streak*2);S.enemy=Math.max(1,S.enemy-dmg);tone(640,.08,.025,'triangle');particles(W*.5,H*.48,12);flash();setHint('Correct. '+S.parts[i][0]+' × '+S.parts[i][1]+' = '+ans+'. '+(S.solved.every(Boolean)?'All sectors charged. COMBINE them.':'Charge another sector.'))}else{S.hp--;S.streak=0;tone(110,.12,.025,'sawtooth');terms[i].classList.add('wrong');setTimeout(()=>terms[i].classList.remove('wrong'),240);setHint('Not quite. Break it smaller if needed. Example: 40 × 20 = 4 × 2 × 100.');if(S.hp<=0){S.hp=2;setHint('Core rebooted. The grid stays intact, so you can keep learning this problem.')}}renderUI()}"
new="function answerTerm(i,v,ans){if(v===ans){S.solved[i]=true;S.lastPart=i;S.streak++;let dmg=14+Math.min(18,S.streak*2);S.enemy=Math.max(1,S.enemy-dmg);tone(640,.08,.025,'triangle');spawnBeam(i,false);particles(W*.5,H*.48,12);flash();setHint('Correct. '+S.parts[i][0]+' × '+S.parts[i][1]+' = '+ans+'. '+(S.solved.every(Boolean)?'All sectors charged. COMBINE them.':'That sector hit the target. Keep the chain alive and charge another.'))}else{S.hp--;S.streak=0;tone(110,.12,.025,'sawtooth');terms[i].classList.add('wrong');setTimeout(()=>terms[i].classList.remove('wrong'),240);setHint('Not quite. Break it smaller if needed. Example: 40 × 20 = 4 × 2 × 100.');if(S.hp<=0){S.hp=2;setHint('Core rebooted. The grid stays intact, so you can keep learning this problem.')}}renderUI()}"
if old not in s: raise SystemExit('answerTerm target missing')
s=s.replace(old,new,1)
old="function answerTotal(v,ans,vals){if(v===ans){S.enemy=0;S.streak+=2;tone(130,.12,.03,'sawtooth');setTimeout(()=>tone(520,.18,.025,'triangle'),60);particles(W*.5,H*.42,34);flash();setHint(vals.join(' + ')+' = '+ans+'. Grid shattered!');renderUI();setTimeout(()=>{S.node++;S.hp=Math.min(S.mhp,S.hp+1);makeProblem()},900)}else{S.hp--;S.streak=0;tone(95,.15,.03);setHint('Check the final addition: '+vals.join(' + ')+'. The decomposition is right, so only the recombination needs fixing.');if(S.hp<=0)S.hp=2;renderUI()}}"
new="function answerTotal(v,ans,vals){if(v===ans){S.enemy=0;S.streak+=2;S.combineFlash=1.1;spawnBeam(0,true);spawnBeam(1,true);spawnBeam(2,true);spawnBeam(3,true);tone(130,.12,.03,'sawtooth');setTimeout(()=>tone(520,.18,.025,'triangle'),60);particles(W*.5,H*.42,34);flash();setHint(vals.join(' + ')+' = '+ans+'. The whole grid fires at once!');renderUI();setTimeout(()=>{S.node++;S.hp=Math.min(S.mhp,S.hp+1);makeProblem()},950)}else{S.hp--;S.streak=0;tone(95,.15,.03);setHint('Check the final addition: '+vals.join(' + ')+'. The decomposition is right, so only the recombination needs fixing.');if(S.hp<=0)S.hp=2;renderUI()}}"
if old not in s: raise SystemExit('answerTotal target missing')
s=s.replace(old,new,1)
start=s.index('function draw(){')
end=s.index('terms.forEach((b,i)=>b.onclick',start)
newdraw="""function draw(){x.clearRect(0,0,W,H);let t=performance.now()/1000,cx=W*.5,cy=H*.47,bob=Math.sin(t*2.4)*4,g=gridGeom();if(S.split){let {A,B,gw,gh,gx,gy,vx,hy,rects}=g;x.fillStyle='rgba(8,18,32,.55)';x.fillRect(gx,gy,gw,gh);rects.forEach((r,i)=>{let charged=S.solved[i],pulse=charged?(0.28+0.1*Math.sin(t*6+i)):.06,col=i===0?'115,220,255':i===1?'255,211,110':i===2?'255,143,179':'178,156,255';x.fillStyle='rgba('+col+','+(charged?pulse:.04)+')';x.fillRect(r.x,r.y,r.w,r.h);x.strokeStyle=charged?'rgba('+col+',.85)':'rgba(96,126,156,.45)';x.lineWidth=charged?2.5:1.2;x.strokeRect(r.x+.5,r.y+.5,r.w-1,r.h-1);x.fillStyle=charged?'#eef8ff':'#9db1c7';x.font='900 10px monospace';x.textAlign='center';x.fillText(S.parts[i][0]+'×'+S.parts[i][1],r.x+r.w/2,r.y+r.h/2-3);x.font='900 9px monospace';x.fillText(charged?String(S.parts[i][0]*S.parts[i][1]):'?',r.x+r.w/2,r.y+r.h/2+10)});x.strokeStyle='#557897';x.lineWidth=1.5;x.strokeRect(gx,gy,gw,gh);x.beginPath();x.moveTo(vx,gy);x.lineTo(vx,gy+gh);x.moveTo(gx,hy);x.lineTo(gx+gw,hy);x.stroke();x.fillStyle='#cfe8ff';x.font='900 9px monospace';x.fillText(A[0],gx+gw*(A[0]/S.a)/2,gy-5);x.fillText(A[1],vx+(gw-vx+gx)/2,gy-5);x.fillText(B[0],gx-16,gy+gh*(B[0]/S.b)/2);x.fillText(B[1],gx-16,hy+(gh-hy+gy)/2)}let shake=S.enemyHit>0?Math.sin(t*90)*7*S.enemyHit*S.enemyHitDir:0;x.save();x.translate(cx+shake,cy+bob);let kind=S.enemyKind,baseCol=kind===0?'#ff8fb3':kind===1?'#ffd36e':kind===2?'#73dcff':'#b29cff';x.strokeStyle=baseCol;x.lineWidth=3+(S.combineFlash>0?1.5:0)+(S.streak>=8?1:0);x.globalAlpha=.9;x.beginPath();if(kind===0){for(let i=0;i<8;i++){let a=i*Math.PI/4,rr=i%2?42:26;x.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}}else if(kind===1){x.rect(-34,-34,68,68);x.moveTo(-45,0);x.lineTo(45,0);x.moveTo(0,-45);x.lineTo(0,45)}else if(kind===2){for(let i=0;i<6;i++){let a=i*Math.PI/3+t*.2;x.lineTo(Math.cos(a)*38,Math.sin(a)*38)}}else{x.arc(0,0,36,0,Math.PI*2);x.moveTo(-48,-8);x.lineTo(48,8);x.moveTo(-40,20);x.lineTo(40,-20)}x.closePath();x.stroke();if(S.enemyHit>0){x.globalAlpha=.22+.35*S.enemyHit;x.fillStyle='#fff';x.beginPath();x.arc(0,0,44+12*S.enemyHit,0,Math.PI*2);x.fill();x.globalAlpha=1}if(S.enemyCracks>0){x.strokeStyle='#eef8ff';x.lineWidth=1.2;for(let i=0;i<S.enemyCracks;i++){let a=i*2.17+.5,r1=15+(i%3)*3,r2=31+(i%4)*4;x.beginPath();x.moveTo(Math.cos(a)*r1,Math.sin(a)*r1);x.lineTo(Math.cos(a+.16)*r2,Math.sin(a+.16)*r2);x.stroke()}}x.fillStyle='#0b1626';x.beginPath();x.arc(0,0,18,0,Math.PI*2);x.fill();x.fillStyle='#fff';x.font='900 13px monospace';x.textAlign='center';x.fillText(S.a+'×'+S.b,0,4);x.restore();for(const b of S.beams){b.t-=1/60;x.globalAlpha=clamp(b.t*2,0,1);x.strokeStyle=b.combine?'#ffd36e':'#73dcff';x.lineWidth=b.combine?4:3;x.beginPath();x.moveTo(b.x1,b.y1);x.lineTo(b.x2,b.y2);x.stroke()}S.beams=S.beams.filter(b=>b.t>0);if(S.enemyHit>0)S.enemyHit=Math.max(0,S.enemyHit-1/34);if(S.combineFlash>0)S.combineFlash=Math.max(0,S.combineFlash-1/30);if(S.comboBurst>0||S.streak>=4){let lvl=Math.min(4,Math.floor(S.streak/4)),rad=54+lvl*10+Math.sin(t*7)*4;x.globalAlpha=.12+lvl*.035;x.strokeStyle=lvl>=3?'#ffd36e':'#73dcff';x.lineWidth=1+lvl*.6;x.beginPath();x.arc(cx,cy,rad,0,Math.PI*2);x.stroke();if(lvl>=2){x.beginPath();x.arc(cx,cy,rad+10,0,Math.PI*2);x.stroke()}x.globalAlpha=1;if(S.comboBurst>0)S.comboBurst=Math.max(0,S.comboBurst-1/60)}if(S.streak>=4){let label=S.streak>=12?'OVERDRIVE':S.streak>=8?'SURGE':'CHAIN';x.fillStyle=S.streak>=12?'#ffd36e':'#73dcff';x.font='900 10px monospace';x.textAlign='center';x.fillText(label+' x'+S.streak,cx,Math.max(26,cy-70))}for(const p of S.particles){p.t-=1/60;p.x+=p.vx/60;p.y+=p.vy/60;x.globalAlpha=clamp(p.t*2,0,1);x.fillStyle='#ffd36e';x.fillRect(p.x,p.y,3,3)}S.particles=S.particles.filter(p=>p.t>0);x.globalAlpha=1;x.textAlign='left';requestAnimationFrame(draw)}requestAnimationFrame(draw);\n"""
s=s[:start]+newdraw+s[end:]
s=s.replace("S.a+' = '+splitNum(S.a).join(' + ')+' and '+S.b+' = '+splitNum(S.b).join(' + ')+'. Every part multiplies every part.'","S.a+' = '+splitNum(S.a).join(' + ')+' and '+S.b+' = '+splitNum(S.b).join(' + ')+'. Each glowing rectangle is one partial product.'")
